template = env.ref('helpdesk_mgmt.mail_template_ticket_confirmacion')
for record in records:
    partner_ids = []
    # Responsable asignado
    if record.user_id and record.user_id.partner_id:
        partner_ids.append(record.user_id.partner_id.id)
    # Contacto del ticket (puede ser el mismo que el admin si el correo coincide)
    if record.partner_id and record.partner_id.id not in partner_ids:
        partner_ids.append(record.partner_id.id)

    # Email del remitente original (cuando no hay partner_id o es distinto)
    email_to_extra = False
    if record.partner_email and not record.partner_id:
        email_to_extra = record.partner_email

    if not partner_ids and not email_to_extra:
        continue

    email_vals = {
        'email_to': email_to_extra or False,
        'recipient_ids': [(4, pid) for pid in partner_ids],
    }
    template.send_mail(record.id, force_send=True, email_values=email_vals)
